type spyStore struct{ mock.Mock }

func (s *spyStore) Save(order Order) error {
    args := s.Called(order)             // records the call
    return args.Error(0)
}

spy := &spyStore{}
_, _ = NewService(spy).Place(order)     // real code runs
spy.AssertCalled(t, "Save", order)      // assert after the fact
spy.AssertNumberOfCalls(t, "Save", 1)
